//! Identify dot-leader and aligned leaderless table-of-contents entries.
use std::collections::HashSet;
use super::super::geometry::Rect;
use super::super::ir::{Alignment,Line,PdfChar,TextBlock,TocEntry};
use super::super::{chars,rtl};
use super::units::{cluster_unit_rows,LineUnit};
pub(super) const LEADER_PAGE_MIN_LINES:usize=10;
pub(super) const LEADER_PAGE_MIN_SHARE:f64=0.3;
fn page_number(s:&str)->bool {jscompat::js_regex!(r"^(?:[0-9]{1,4}|[ivxlcdm]{1,6})$","i").test(s)}
fn leader_match(s:&str)->Option<(String,String)>{let re=jscompat::js_regex!(r"^(.*?[^\s._\-–—])\s*([.·_\-–—]\s*){4,}\s*([0-9]{1,4}|[ivxlcdm]{1,6})\s*$","i");let m=re.exec(s)?;Some((m.get(1)?.into(),m.get(3)?.into()))}
pub(super) fn has_dot_leader_run(chars:&[PdfChar])->bool {
    let(mut count,mut armed,mut i)=(0,false,0);while i<chars.len(){let c=&chars[i];if [".","·","_","-","–","—"].contains(&c.text.as_str()){count+=1;if count>=4{armed=true;}i+=1;}else if c.text==" "||c.code==0x20{i+=1;}else if armed && c.text.as_bytes().first().is_some_and(u8::is_ascii_alphanumeric){let mut j=i;while j<chars.len()&&chars[j].text.as_bytes().first().is_some_and(u8::is_ascii_alphanumeric){j+=1;}let token:String=chars[i..j].iter().map(|c|c.text.as_str()).collect();if chars[j..].iter().all(|c|c.text==" "||c.code==0x20)&&page_number(&token){return true;}count=0;armed=false;i=j;}else{count=0;armed=false;i+=1;}}false
}
fn spans_before(line:&Line,end:usize)->Vec<super::super::ir::Span>{let(mut at,mut out)=(0,Vec::new());for span in &line.spans{let take=span.text.len().min(end.saturating_sub(at));if take>0{let take=(0..=take).rev().find(|&i|span.text.is_char_boundary(i)).unwrap_or(0);let text=span.text[..take].trim_end();if !text.is_empty(){let mut s=span.clone();s.text=text.into();out.push(s);}}at+=span.text.len();if at>=end{break;}}out}
fn make_block(lines:Vec<Line>,bounds:Rect,level:usize,num:String)->TextBlock{let direction=rtl::first_strong_dir(&lines);TextBlock{lines,bounds,align:Alignment::Left,first_line_indent_pt:0.0,direction,list:None,stitched_from_line:None,toc_entry:Some(TocEntry{level,page_number:num}),spacing_before_pt:None,border:None,card_id:None}}
pub(super) fn detect_toc_blocks(blocks:Vec<TextBlock>)->Vec<TextBlock>{
    let min_x=blocks.iter().filter(|b|b.list.is_none()).flat_map(|b|&b.lines).filter(|l|leader_match(&l.spans.iter().map(|s|s.text.as_str()).collect::<String>()).is_some()).map(|l|l.bounds.x0).reduce(f64::min);let Some(min_x)=min_x else{return blocks;};let mut out=Vec::new();
    for b in blocks {if b.list.is_some()||!b.lines.iter().any(|l|leader_match(&l.spans.iter().map(|s|s.text.as_str()).collect::<String>()).is_some()){out.push(b);continue;}let mut plain=Vec::new();for line in &b.lines{let all:String=line.spans.iter().map(|s|s.text.as_str()).collect();if let Some((title,num))=leader_match(&all){if !plain.is_empty(){let mut p=b.clone();p.bounds=plain.iter().map(|l:&Line|l.bounds).reduce(Rect::union).unwrap();p.lines=std::mem::take(&mut plain);out.push(p);}let mut titled=line.clone();let spans=spans_before(line,title.len());if !spans.is_empty(){titled.spans=spans;}let level=(1+(line.bounds.x0-min_x).max(0.0).div_euclid(14.0) as usize).min(9);out.push(make_block(vec![titled],line.bounds,level,num));}else{plain.push(line.clone());}}if !plain.is_empty(){let mut p=b.clone();p.bounds=plain.iter().map(|l|l.bounds).reduce(Rect::union).unwrap();p.lines=plain;out.push(p);}}out
}
fn rank(s:&str)->i64{let vals:Vec<i64>=s.to_ascii_lowercase().chars().map(|c|match c{'i'=>1,'v'=>5,'x'=>10,'l'=>50,'c'=>100,'d'=>500,'m'=>1000,_=>0}).collect();vals.iter().enumerate().map(|(i,&v)|if vals.get(i+1).copied().unwrap_or(0)>v{-v}else{v}).sum()}
#[derive(Clone)] struct Cand {units:Vec<LineUnit>,bounds:Rect,num:LineUnit,roman:bool,value:i64}
pub(super) fn detect_toc_rows(units:&[LineUnit])->(Vec<TextBlock>,Vec<LineUnit>){
    let rows=cluster_unit_rows(units);let mut cands:Vec<Option<Cand>>=Vec::new();for row in rows{if row.units.len()<2{cands.push(None);continue;}let num=row.units.last().unwrap().clone();let text=num.chars.iter().map(|c|c.text.as_str()).collect::<String>();let text=text.trim();if !page_number(text){cands.push(None);continue;}let roman=text.chars().all(|c|"ivxlcdmIVXLCDM".contains(c));let value=if roman{rank(text)}else{text.parse().unwrap_or(0)};cands.push(Some(Cand{units:row.units,bounds:row.bounds,num,roman,value}));}
    let(mut out,mut consumed)=(Vec::new(),HashSet::new());let accept=|run:&mut Vec<Cand>,out:&mut Vec<TextBlock>,consumed:&mut HashSet<usize>|{if run.len()<3{run.clear();return;}let em=if run[0].num.font_size==0.0{12.0}else{run[0].num.font_size};let left=run.iter().map(|c|c.num.bounds.x1).fold(f64::INFINITY,f64::min);let right=run.iter().map(|c|c.num.bounds.x1).fold(f64::NEG_INFINITY,f64::max);if right-left>1.5*em{run.clear();return;}let(mut arabic,mut prev,mut invalid)=(false,-1,false);for c in run.iter(){if c.roman&&arabic{invalid=true;break;}if !c.roman&&!arabic{arabic=true;prev=-1;}if c.value<prev{invalid=true;break;}prev=c.value;}if invalid{run.clear();return;}
        let min_x=run.iter().map(|c|c.bounds.x0).fold(f64::INFINITY,f64::min);for c in run.iter(){let glyphs:Vec<_>=c.units[..c.units.len()-1].iter().flat_map(|u|u.chars.iter().cloned()).collect();let lines=chars::analyze_chars(&glyphs);if lines.is_empty(){continue;}let number=c.num.chars.iter().map(|c|c.text.as_str()).collect::<String>().trim().to_owned();let level=(1+((c.bounds.x0-min_x)/14.0).floor().max(0.0) as usize).min(9);out.push(make_block(lines,c.bounds,level,number));for u in &c.units{consumed.insert(u.id);}}run.clear();};
    let mut run:Vec<Cand>=Vec::new();for cand in cands{if let Some(c)=cand{if run.last().is_some_and(|p|p.bounds.y0-c.bounds.y1>2.5*p.bounds.height().max(1.0)){accept(&mut run,&mut out,&mut consumed);}run.push(c);}else{accept(&mut run,&mut out,&mut consumed);}}accept(&mut run,&mut out,&mut consumed);(out,units.iter().filter(|u|!consumed.contains(&u.id)).cloned().collect())
}
